/* Helper: map safari card index to its image + srcSet */
function getSafariImage(i: number) {
  const idx = i % 5;
  const map = [
    elephantPortrait,
    ethicalImg,
    wildlife,
    landscape,
    elephantPortrait,
  ] as const;
  return map[idx];
}

